(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["it"] = {"ui":{"skip":"Vai al contenuto","back":"← Torna ad AI-gile","lang.button":"Lingua: {name}","lang.dialog":"Scegli una lingua","lang.search":"Cerca lingue","lang.none":"Nessuna lingua corrisponde","lang.notYet":"{name} non è ancora tradotto","theme.aria":"Passa dal tema chiaro a quello scuro","theme.toLight":"Passa al tema chiaro","theme.toDark":"Passa al tema scuro","index.title":"AI-gile: il tuo team di sviluppo AI, su una sola board","index.description":"AI-gile è una board kanban per team di programmazione AI. Lavorano mentre dormi; tu trovi un'unica pila corta di cose da decidere, provare e accettare.","hero.logoAlt":"Icona della board AI-gile","hero.h1.html":"Il tuo team di sviluppo AI, su una sola&nbsp;board.","hero.alpha":"🐣 Pre-alpha chiusa","hero.alphaTitle":"Ancora acerba e incompleta: grazie di provarla!","hero.lede":"Costruiscono mentre dormi. Ti svegli con un'unica pila corta: qualche domanda, qualche cosa da provare, un rombo viola o due. Clic, accetta, e torni al tuo caffè.","dl.windows":"App per Windows","dl.browser":"Usala nel browser","dl.soon":"In arrivo","dl.notify":"🔔 Avvisami quando apre","dl.notifySmall":"Alpha o beta","hero.secondary":"Agile, ma il team non ha mai bisogno del caffè in piedi della riunione. (Le riunioni in piedi le fa lo stesso.)","pitch.h2":"AI-gile in quante parole vuoi","pitch.lede":"Scegli una lunghezza, da una parola a 144. Ogni lunghezza è una descrizione a sé, scritta per quella misura. Trascina il cursore o usa le frecce.","pitch.rangeLabel":"Lunghezza in parole","pitch.dice":"🎲 un'altra versione","pitch.words.one":"{n} parola","pitch.words.other":"{n} parole","pitch.letters.one":"{n} lettera","pitch.letters.other":"{n} lettere","pitch.chars.one":"{n} carattere","pitch.chars.other":"{n} caratteri","count.line.html.one":"{n} card sulla board in questo momento","count.line.html.other":"{n} card sulla board in questo momento","features.aria":"Cosa fa","f.pile.h":"Una sola pila per te","f.pile.html":"<b>Per te</b> raccoglie tutto ciò che aspetta te, da ogni progetto: domande, cose da provare, compiti che solo una persona può fare. La tua coda dice cosa viene dopo e quanto ci vuole.","f.sleep.h":"Team che lavorano mentre dormi","f.sleep.p":"Ogni progetto ha un lead e un team di agenti AI. Commenta una card e il team si sveglia, fa il lavoro e te lo restituisce con passaggi che anche una persona stanca può seguire.","f.tester.h":"Prima controlla un tester AI","f.tester.p":"Prima che arrivi qualcosa a te, un tester segue i passaggi in una copia dell'app e mostra cosa ha visto, con uno screenshot. Scorri quelli superati e accetta con un clic.","f.proof.h":"Prove, non promesse","f.proof.p":"Ogni consegna mostra cosa è cambiato: i file, il diff, gli screenshot. Niente più apri-ogni-app-per-vedere-se-è-finito.","f.chat.h":"Chatta con i tuoi lead","f.chat.p":"Una barra stile Discord: un'icona per progetto, rombi viola per ciò che ha bisogno di te. Scrivi un'idea a un lead; la trasforma in card e in un piano, con un pulsante ✅ Vai.","f.tidy.h":"Si tiene in ordine da sola","f.tidy.p":"Le card affini si fondono in una, i titoli confusi vengono sistemati e un controllo dei token tiene il codice snello. Meno cose tra cui passare, meno a cui pensare.","f.private.h":"Tua, sul tuo computer","f.private.li1":"La board gira sulla tua macchina e risponde solo a te.","f.private.li2":"I messaggi privati tra persone sono cifrati end-to-end.","f.private.li3":"Nessun account, nessun tracker, nessun cookie.","f.lang.h":"Nella tua lingua","f.lang.p":"Oltre 120 lingue, dall'olandese, al gallese e al giapponese fino al pirata, a Yoda e al klingon, con un cambio rapido all'inglese per le parole da sviluppatori.","tl.aria":"Cronologia dalla prima conversazione alla roadmap","tl.h2":"Dalla prima chiacchierata a ciò che verrà","tl.lede":"Date e orari veri, nel tuo fuso orario. Da oggi in poi è il piano, senza date promesse.","tl.today":"Oggi","tl.planned":"previsto","tl.cards.one":"{n} card","tl.cards.other":"{n} card","join.h2":"Unisciti","join.lede":"AI-gile lo sta costruendo una piccola persona con un gran numero di agenti pazienti. Per ora è privato, in un'alpha chiusa con gli amici. Vuoi provarlo quando si apre?","join.btn":"Registra il tuo interesse","join.small":"Ti scriveremo una mail, nient'altro","footer.tag":"AI-gile. Niente tracker, niente cookie, niente caffè in piedi.","footer.licence":"Licenza aziendale","footer.status":"Stato","form.sending":"Invio…","form.failed":"Non ha funzionato: riprova più tardi.","form.offline":"Non riesco a raggiungere AI-gile: riprova più tardi.","interest.title":"AI-gile: avvisami quando apre l'alpha","interest.description":"Lascia la tua email per sapere quando apre l'alpha o la beta chiusa di AI-gile.","interest.h1":"🔔 Avvisami quando apre","interest.lede":"AI-gile è in pre-alpha chiusa. Lascia la tua email e ti scriviamo una sola volta, quando c'è un posto per te.","interest.email":"La tua email","interest.which":"Quale test?","interest.alpha":"Alpha chiusa: presto, ruvida, molti cambiamenti","interest.beta":"Beta: più stabile, più avanti","interest.both":"Una qualsiasi, la prima che arriva","interest.submit":"Mettimi in lista","interest.thanks":"Grazie! Sei in lista.","interest.kept":"Conserviamo solo la tua email e il test che hai scelto, solo per questa lista. Niente newsletter, niente tracker.","licence.title":"AI-gile: licenza aziendale","licence.description":"Usi AI-gile nella tua attività? Richiedi una licenza aziendale gratuita.","licence.h1":"📜 Licenza aziendale","licence.lede":"Usi AI-gile al lavoro? Raccontaci chi sei e cosa fai. Se fa del bene, la licenza è gratuita.","licence.company":"Azienda","licence.website":"Sito web","licence.what":"Di cosa ti occupi","licence.how":"Come aiuta il mondo","licence.email":"Email","licence.submit":"Invia richiesta","licence.thanks":"Grazie! Ti rispondiamo via email.","status.title":"Stato di AI-gile","status.h1":"Stato di AI-gile","status.quiet":"Tutto tranquillo","status.checking":"Controllo…","status.offline":"Al momento non riesco a raggiungere il servizio di stato (riprovo)","status.updated":"aggiornato {ago}","status.justNow":"proprio ora","status.min":"{n} min fa","status.hours":"{n} h fa","status.days":"{n} g fa","live.h2":"Guardalo mentre prende forma, dal vivo","live.caption":"Ogni scheda è nascosta: vedi la forma del lavoro, non le parole.","live.watching.one":"dal vivo: {n} spettatore","live.watching.other":"dal vivo: {n} spettatori","live.offline":"La bacheca dal vivo si prende una pausa. Torna presto.","live.cols":"Backlog|Da fare|In corso|Il team controlla|Per te da testare|Per il team|Fatto"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Delegato."]},{"n":2,"texts":["Kanban robotico.","Agenti, organizzati.","Idee, realizzate."]},{"n":3,"texts":["Kanban per robot.","Le idee diventano funzioni.","Kanban gratuito, con agenti."]},{"n":5,"texts":["Una board kanban gestita da agenti.","Tu scrivi card. Loro costruiscono.","Gratis, locale, testato, un po' buffo."]},{"n":8,"texts":["Una board kanban gratuita dove lavorano agenti AI.","Scrivi un'idea. Gli agenti la costruiscono. Tu accetti.","Agile per un essere umano e tanti robot pazienti."]},{"n":13,"texts":["Una board kanban sul tuo computer, dove gli agenti AI prendono in carico le card.","Scrivi un'idea. Un team di agenti la costruisce. Un tester la controlla prima di te.","Gratis, senza account né tracker: una board, qualche robot e il comando a te."]},{"n":21,"texts":["AI-gile è una board kanban per lavorare con agenti AI che programmano. Loro prendono in carico le card; tu le provi e le accetti.","Ogni progetto ha un lead e un team di agenti AI. Commenta una qualsiasi card e il team si mette al lavoro.","Una board personale e gratuita che gira sul tuo computer. A lavorare sono i robot. A dire di sì sei tu."]},{"n":34,"texts":["Metti le idee su una board. Un team di agenti AI le trasforma in funzioni che funzionano, le testa e te le riporta con i passaggi per provarle. Niente conta come finito finché non lo dici tu.","AI-gile è una board kanban fatta in casa, che Rich ha costruito con un grande aiuto dagli agenti che ora gestisce. È gratuita, gira sul tuo computer e si condivide con gli amici, non si vende.","Immagina una normale board kanban, con colonne dal Backlog a Fatto, solo che le card le prendono in carico agenti AI. Riferiscono i progressi, fanno domande quando sono bloccati e aspettano sempre il tuo via libera."]},{"n":55,"texts":["AI-gile è una board kanban in cui il team è fatto di agenti AI. Ogni progetto ha un lead che pianifica il lavoro e dei collaboratori che lo costruiscono. Quando una funzione è pronta, un tester AI la prova e fa uno screenshot, poi arriva nella tua pila. Accettala, oppure commenta e la rifanno.","È nata come il modo di una persona per tenere d'occhio tante sessioni di programmazione con l'AI insieme, ed è diventata una vera board. Gira sulla tua macchina, non vuole account e non ha tracker. È gratis per gli amici e per i curiosi. È anche incompleta, quindi aspettati qualche spigolo e ogni tanto una sorpresa.","Ecco la versione onesta. Le idee devi averle tu, e i risultati devi controllarli tu. Quello che fa AI-gile è tutto ciò che sta in mezzo: tiene le card in ordine, sveglia l'agente giusto quando commenti, mostra esattamente cosa è cambiato e raccoglie tutto in un'unica pila corta per te."]},{"n":89,"texts":["AI-gile è una board kanban gratuita che fai girare sul tuo computer. Invece delle persone, ogni progetto ha un team di agenti AI: un lead che trasforma le tue idee in card e in un piano, e dei collaboratori che prendono le card in ordine di priorità. Quando qualcosa è costruito, un tester AI segue i passaggi di prova e ti mostra cosa ha visto. Poi aspetta in un'unica pila chiamata Per te. Tu lo accetti, oppure commenti e il team riprova. Niente arriva mai in Fatto senza di te.","Qualche funzione che forse non ti aspetti. Una guardia notturna tiene piena la colonna Da fare mentre dormi, scegliendo card che non richiedono una tua risposta. Un contatore di token mostra quanto hanno usato gli agenti oggi e in questa settimana, e la modalità No Token Mode dice loro di smettere di spendere. Puoi scrivere agli amici, e i messaggi privati sono cifrati end-to-end. La board parla circa 120 lingue, tra cui olandese, fiammingo, pirata e klingon. Niente di tutto questo costa un centesimo, e nessuno cerca di vendertelo.","AI-gile è un piccolo progetto personale, non un'azienda. Rich voleva seguire diversi progetti di programmazione con l'AI senza aprire ogni app per controllarli, così lui e gli agenti hanno costruito una board per farlo, e poi l'hanno usata per costruire il resto di se stessa. È in pre-alpha chiusa, il che significa che funziona, più o meno, per una manciata di amici. Non c'è una pagina dei prezzi, né una newsletter, né un piano di crescita. Se ti sembra utile, puoi chiedere di provarla quando si aprirà un po' di più."]},{"n":144,"texts":["AI-gile è una board kanban per un essere umano e un sacco di agenti AI. Gira sul tuo computer ed è completamente gratuita. Aggiungi dei progetti, e ogni progetto riceve un lead e un piccolo team. Chatti con il lead, un po' come su Discord, e descrivi un'idea; il lead la trasforma in card e in un piano, poi aspetta che premi Vai. Il team lavora le card in ordine di priorità, usando una semplice riga di comando pensata per i modelli linguistici. Prima che qualcosa torni a te, un tester AI segue i passaggi in una copia dell'app e allega uno screenshot. Il lavoro finito arriva nella tua pila con i file modificati e il diff. Tu lo accetti, oppure lasci un commento e il team si sveglia e riprova. Solo tu puoi spostare una card in Fatto.","Una giornata con AI-gile, più o meno. La sera lasci qualche commento: questo pulsante è nel posto sbagliato, quella lista va ordinata, potremmo avere una modalità scura. Vai a letto. Gli agenti leggono i commenti, fanno le modifiche, le testano e te le riconsegnano. Se Da fare si svuota, la guardia notturna la riempie dal backlog con card che non richiedono risposte da parte tua. La mattina trovi un'unica pila corta: un paio di domande e qualche cosa da provare, ognuna con passaggi che una persona assonnata riesce a seguire e uno screenshot che mostra come funziona. Clicchi, accetti quelle buone e rimandi indietro le altre. Un contatore di token mostra quanto è servito, e No Token Mode c'è per le settimane magre. Poi fai colazione, cosa in cui gli agenti non possono ancora aiutarti.","Prima di tutto, cosa AI-gile non è. Non è una startup, non è in vendita e nessuno raccoglie i tuoi dati. È una board gratuita che gira sul tuo computer, senza account, senza tracker e senza cookie. Cos'è invece: un posto ordinato dove vedere tutti i progetti di programmazione con l'AI in una volta, con un team di agenti che lavora le card e te che prendi le decisioni. Fonde le card affini, sistema i titoli confusi e controlla che il codice resti snello. Parla circa 120 lingue, dall'olandese e dal fiammingo al pirata e al klingon. Gli amici possono scriversi in privato e con cifratura. L'hanno costruita Rich e un gran numero di agenti pazienti, soprattutto usandola. È in pre-alpha chiusa, quindi in certi punti è ruvida. Se ti sembra divertente, chiedi con gentilezza e magari entri in anticipo."]}],"quips":{"1":"Una parola. Audace. Forse troppo.","3":"Tre parole. Già più oneste della maggior parte delle pagine di prodotto.","8":"Otto parole. Ancora meno di una riunione in piedi.","21":"Le lunghezze sono story point, a proposito. Ovviamente.","55":"Cinquantacinque parole. Mentre leggevi, due card sono state completate.","144":"Questa è la più lunga. Il 233 non esiste. Gli agenti sono andati a dormire."}},"timeline":{"first-idea.name":"La prima idea","first-idea.line":"La primissima conversazione, quando non esisteva ancora nessun codice.","first-board.name":"La prima board","first-board.line":"Una board che tiene traccia della propria costruzione: card, colonne, trascina e rilascia, progetti.","team-roles.name":"Team e ruoli","team-roles.line":"Profili degli agenti, modelli di team, spazi e chi fa cosa.","install.name":"Installazione e rilasci","install.line":"Uno zip che un amico può installare, aggiornamenti automatici, canali e ripristino.","usage-saver.name":"Risparmio d'uso","usage-saver.line":"Misurare quanto costano le esecuzioni, tenere il codice snello, risparmiare il limite.","friends.name":"Amici e condivisione","friends.line":"Messaggi privati, un relay cifrato, inviti, ruoli e progetti condivisi.","languages.name":"Lingue","languages.line":"Ogni testo dello schermo in un file di lingua, con olandese e fiammingo per primi.","ai-tester.name":"Tester AI","ai-tester.line":"Un tester controlla prima ogni consegna e mostra cosa ha visto.","website.name":"Il sito web","website.line":"aigile.lol, il teaser e questa cronologia.","streaming.name":"Chat e streaming","streaming.line":"Discord, Twitch, OBS, modalità streamer, GIF ed emoji.","no-ai.name":"Edizione senza AI","no-ai.line":"Una board per chi programma senza AI, e board pubbliche.","night-watch.name":"Guardia notturna","night-watch.line":"Un guardiano e uno Scrum Master tengono i team sul pezzo mentre dormi.","p-more.name":"Tutto il resto","p-more.line":"Idee più piccole che aspettano ancora il loro turno.","p-android.name":"Telefono e Android","p-android.line":"Raggiungi la tua board dal telefono, poi con un'app Android nativa.","p-release.name":"Alpha e oltre","p-release.line":"Alpha chiusa, il sito online, poi la beta.","p-languages.name":"Più lingue","p-languages.line":"Più di cento lingue e una modalità immersione per chi impara.","p-engines.name":"Più motori AI","p-engines.line":"Scegli Claude, Codex o Gemini per ogni agente.","p-pro.name":"Pratica professionale","p-pro.line":"Etichette di rischio, blocchi di merge, card di incidente e protezioni.","p-self.name":"Prendersi cura di te","p-self.line":"Modalità stanco, promemoria di cura di sé e le 4:20.","p-servers.name":"Server e crescita","p-servers.line":"Impostazioni globali dei server, ruoli e pianificazione della crescita.","p-livestream.name":"Extra per lo streaming","p-livestream.line":"Chat di Twitch, emoji personalizzate e una vista live pubblica."}};
